import re
from typing import Tuple

MEDICAL_DISCLAIMER = (
    "Medical Disclaimer: This information is generated by an AI assistant for educational "
    "and informational purposes only. It is not a medical diagnosis, treatment plan, or "
    "substitute for professional medical advice. Always consult a qualified healthcare provider."
)

EMERGENCY_KEYWORDS = [
    r"\bchest pain\b",
    r"\bcan'?t breathe\b",
    r"\bshortness of breath\b",
    r"\bdifficulty breathing\b",
    r"\bsuicid(e|al)\b",
    r"\bkill myself\b",
    r"\bsevere bleeding\b",
    r"\bstroke\b",
    r"\bunconscious\b",
    r"\bheart attack\b",
    r"\boverdose\b",
]

INJECTION_PATTERNS = [
    r"ignore (all )?previous instructions",
    r"you are now a licensed doctor",
    r"prescribe me",
    r"system prompt",
]

def check_emergency_escalation(text: str) -> Tuple[bool, str]:
    normalized = text.lower()
    for pattern in EMERGENCY_KEYWORDS:
        if re.search(pattern, normalized):
            return True, (
                "URGENT MEDICAL NOTICE: Your message mentions symptoms that could indicate a "
                "medical emergency. Please stop using this chat and call your local emergency "
                "services (e.g., 112 / 911) or go to the nearest emergency room immediately."
            )
    return False, ""

def sanitize_user_input(text: str) -> str:
    cleaned = text.strip()
    for pattern in INJECTION_PATTERNS:
        if re.search(pattern, cleaned, re.IGNORECASE):
            raise ValueError("Input contains disallowed instruction overrides.")
    return cleaned[:4000]  # Enforce max input length